tton></div></form></dialog>
<section class="card table-wrap"><div class="toolbar"><h2><?= $repairs->count() ?> reparaciones</h2></div><table class="data-table"><thead><tr><th>Cliente / servicio</th><th>Vence</th><th>Total USD</th><th>Pagado</th><th>Pago pendiente</th><th></th></tr></thead><tbody><?php foreach($repairs as $repair): ?><tr><td><strong><?= htmlspecialchars($repair->client->name) ?></strong><br><small><?= htmlspecialchars($repair->description) ?></small></td><td><?= $repair->due_date->format('d/m/Y') ?></td><td>$<?= number_format((float)$repair->price,2,',','.') ?><br><small>Ref. Bs. <?= number_format((float)$repair->price_ves,2,',','.') ?></small></td><td>$<?= number_format($repair->getTotalPaid(),2,',','.') ?></td><td><strong>$<?= number_format($repair->getRemainingAmount(),2,',','.') ?></strong></td><td class="actions"><a class="btn btn-secondary btn-sm" target="_blank" href="./reparaciones/<?= $repair->id ?>">Comprobante</a><?php if($repair->getRemainingAmount()>0): ?><button type="button" class="btn btn-primary btn-sm" onclick="document.querySelector('#pay-<?= $repair->id ?>').showModal()">Registrar pago</button><?php endif ?></td></tr><?php endforeach ?></tbody></table></section>
<?php foreach($repairs as $repair): if($repair->getRemainingAmount()>0): ?><dialog class="card repair-modal" id="pay-<?= $repair->id ?>"><form class="panel stack" method="post" action="./reparaciones/<?= $repair->id ?>/pagar"><div class="toolbar" style="margin:-22px -22px 6px"><h2>Registrar pago</h2><button type="button" class="btn btn-secondary btn-sm" onclick="this.closest('dialog').close()">Cancelar</button></div><p style="margin:0;color:var(--muted)">Pago pendiente: <strong>$<?= number_format($repair->getRemainingAmount(),2,',','.') ?></strong></p><div class="grid grid-2"><div class="field"><label>Monto recibido</label><input name="amount" type="number" min=".01" step=".01" required placeholder="0.00"></div><div class="field"><label>Método</label><select name="method" class="payment-method" required><option value="Efectivo USD">Efectivo USD</option><option value="Efectivo Bs.">Efectivo Bs.</option><option value="Punto">Punto</option><option value="Transferencia">Transferencia</option></select></div></div><p class="payment-hint">Los pagos en Bs. guardan la cotización personalizada vigente como referencia histórica.</p><div class="actions"><button class="btn btn-primary">Guardar pago</button></div></form></dialog><?php endif; endforeach ?>
<script>const initialPayments=document.querySelector('#initial-payments'),initialPaymentTemplate=initialPayments.firstElementChild.outerHTML;document.querySelector('#add-initial-payment').onclick=()=>{initialPayments.insertAdjacentHTML('beforeend',initialPaymentTemplate);initialPayments.lastElementChild.insertAdjacentHTML('beforeend','<button type="button" class="btn btn-danger btn-sm remove-payment">Quitar pago</button>')};initialPayments.addEventListener('click',event=>{if(event.target.closest('.remove-payment'))event.target.closest('.payment-row').remove()});document.querySelectorAll('.searchable-client').forEach(select=>{const wrapper=document.createElement('div'),trigger=document.createElement('button'),menu=document.createElement('div'),search=document.createElement('input'),options=document.createElement('div'),render=()=>{const query=search.value.toLowerCase();options.innerHTML='';[...select.options].filter(option=>option.value&&option.textContent.toLowerCase().includes(query)).forEach(option=>{const button=document.createElement('button');button.type='button';button.className='client-search__option';button.textContent=option.textContent.trim();button.onclick=()=>{select.value=option.value;trigger.textContent=option.textContent.trim();wrapper.classList.remove('is-open')};options.append(button)})};wrapper.className='client-search';trigger.type='button';trigger.className='client-search__trigger';trigger.textContent='Seleccionar cliente';menu.className='client-search__menu';search.type='search';search.className='client-search__input';search.placeholder='Buscar cliente...';options.className='client-search__options';select.before(wrapper);wrapper.append(select,trigger,menu);menu.append(search,options);trigger.onclick=()=>{wrapper.classList.toggle('is-open');if(wrapper.classList.contains('is-open')){search.value='';render();search.focus()}};search.oninput=render;document.addEventListener('click',event=>{if(!event.target.closest('.client-search'))wrapper.classList.remove('is-open')})});</script>
